%% Example: theoretical circulation over one of the FUNWAVE bar-rip grids
% Run after the existing ripchannel utilities have been added to the path.

runBATHY = 'spreadRip';
grid     = 'barRip1';
runWAVES = 'h10t10s10d00';  % Hs=1 m, Tp=10 s, spread=10 deg, Dp=0 deg

info = prep_local_ripchannel_info(runBATHY,[grid,'_',runWAVES]);
% info.h, info.x and info.y are regenerated by make_ripchannel_bathy.
info = make_ripchannel_bathy(info,0);

opts = struct();
opts.source    = 'both';      % 'bonneton', 'bowen', or 'both'
opts.spread    = info.spread; % degrees; override to 1, 2, 4, 10, 20 etc.
opts.theta0    = info.Dp;     % degrees relative to shore-normal in this code
opts.ndir      = 9;           % odd number of directional bins (e.g. 5, 9, 15)
opts.gamma     = 0.78;
opts.nu        = 5.0;         % m^2/s, sensitivity parameter
opts.drag      = 0.03;        % 1/s, sensitivity parameter
opts.maxCells  = 180000;
opts.doPlot    = true;
opts.saveFile  = [info.rootMat,grid,'_',runWAVES,'_theory.mat'];

out = ripchannel_theory_circulation(info,opts);

